function validate(){if(p.rowHeaderColumnId&&!p.columns.some(column=>column.id===p.rowHeaderColumnId))throw new TypeError('rowHeaderColumnId must identify an existing column');}validate();$effect(validate);let region:HTMLDivElement;let table:HTMLTableElement;let overflow=$state(false),position=$state(0),limit=$state(0);function measure(){if(!region)return;overflow=region.scrollWidth>region.clientWidth+1;position=region.scrollLeft;limit=region.scrollWidth-region.clientWidth-1;}onMount(()=>{const observer=new ResizeObserver(measure);observer.observe(region);observer.observe(table);measure();return()=>observer.disconnect();});$effect(()=>{p.columns;p.rows;queueMicrotask(measure);});function scroll(direction:number){region.scrollBy({left:direction*Math.max(1,region.clientWidth*.8),behavior:'instant'});measure();}const uid=$props.id();function sort(id:string){p.onSortChange?.({columnId:id,direction:p.sort?.columnId===id&&p.sort.direction==='ascending'?'descending':'ascending'});}
</script>
<div><!-- svelte-ignore a11y_no_noninteractive_tabindex (A named overflow region receives native keyboard scroll focus.) -->
